def parse(raw, limit=65536):
    require(type(raw) is bytes and len(raw) <= limit, "INVALID_JSON_SIZE")
    def pairs(items):
        result = {}
        for key, value in items:
            require(key not in result, "DUPLICATE_JSON_KEY")
            result[key] = value
        return result
    def invalid_constant(_):
        raise ProtocolError("NONFINITE_JSON")
    try:
        value = json.loads(raw.decode("utf-8"), object_pairs_hook=pairs,
                           parse_constant=invalid_constant)
        canonical(value)  # Reject unpaired Unicode surrogates and nonfinite exponents.
        return value
    except (ValueError, UnicodeError, RecursionError):
        raise ProtocolError("INVALID_JSON") from None

def validate(kind, value):
    check(value, SCHEMAS[kind])
    if kind in ("request", "project"):
        refs = value["authoritative_contracts"]
        require(len({x["reference"] for x in refs}) == len(refs), "DUPLICATE_REFERENCE")
        for item in refs:
            safe_reference(item["reference"])
    if kind == "request":
        evidence = value["implementation_evidence"]
        require(len({x["label"] for x in evidence}) == len(evidence), "DUPLICATE_EVIDENCE")
        for item in evidence:
            safe_reference(item["source_reference"])
            require(digest(item["content"].encode("utf-8")) == item["sha256"],
                    "EVIDENCE_HASH_MISMATCH")
    if kind == "response":
        if value["verdict"] == "GO":
            require(not value["blocking_findings"] and not value["required_repairs"],
                    "CONTRADICTORY_GO")
        if value["verdict"] == "NO_GO":
            require(bool(value["blocking_findings"]) and bool(value["required_repairs"]),
                    "EMPTY_NO_GO")
    return value

def safe_reference(reference):
    # References are labels only: never open, resolve, discover, or upload them.
    parts = reference.split("#", 1)[0].split("/")
    require(all(part not in ("", ".", "..") and not part.startswith(".") for part in parts),
            "UNSAFE_REFERENCE")

def classify_response(raw, state, current_head, policy):
    """Return verdict/classification, rejection reason, and validated envelope.

    reason NONE means a valid matching wire verdict, including INVALID_RESPONSE.
    Local rejection instead returns a specific reason and no validated envelope.
    """
    active = state["active_handoff"]
    require(active is not None, "PENDING_HANDOFF_REQUIRED")
    try:
        response = validate("response", parse(raw, policy["max_response_bytes"]))
    except ProtocolError:
        return "INVALID_RESPONSE", "SCHEMA_INVALID", None
    if response["handoff_id"] != active["handoff_id"]:
        return "INVALID_RESPONSE", "WRONG_HANDOFF", None
    if response["reviewed_head"] != active["originating_head"] or current_head != active["originating_head"]:
        return "INVALID_RESPONSE", "STALE_HEAD", None
    return response["verdict"], "NONE", response

"""Explicit local commands only. No GUI, network, daemon, or automatic retries."""
import argparse
from pathlib import Path
import subprocess
import sys

from .protocol import (
    HEAD, ProtocolError, SCHEMAS, canonical, check, parse,
)
from .store import Store, regular_read


def git_head(directory):
    try:
        raw = subprocess.run(
            ["git", "-C", str(directory), "rev-parse", "--verify", "HEAD"],
            check=True, capture_output=True, timeout=10,
        ).stdout.decode("ascii").strip()
        check(raw, HEAD)
        return raw
    except (OSError, ValueError, subprocess.SubprocessError):
        raise ProtocolError("HEAD_UNAVAILABLE") from None


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--control-dir", type=Path, default=Path(".orchestration"))
    parser.add_argument("--repository", type=Path, default=Path("."))
    commands = parser.add_subparsers(dest="command", required=True)
    schema = commands.add_parser("schema", help="Print an exact portable JSON Schema.")
    schema.add_argument("kind", choices=SCHEMAS)
    for name in ("validate", "recover", "bootstrap", "delivered", "complete"):
        commands.add_parser(name)
    create = commands.add_parser("create", help="Persist an explicitly curated request; no delivery.")
    create.add_argument("request", type=Path)
    accept = commands.add_parser("respond", help="Ingest a saved reviewer response; no fetch.")
    accept.add_argument("response", type=Path)
    gate = commands.add_parser("gate")
    gate.add_argument("reason", choices=("TRANSPORT_UNCONFIRMED", "RESPONSE_MISSING", "OPERATOR_REQUEST"))
    args = parser.parse_args(argv)
    try:
        if args.command == "schema":
            sys.stdout.buffer.write(canonical({
                "$schema": "https://json-schema.org/draft/2020-12/schema", **SCHEMAS[args.kind]}))
            return 0
        store = Store(args.control_dir)
        if args.command in ("validate", "recover"):
            state = getattr(store, args.command)()
        else:
            head = git_head(args.repository)
            if args.command == "bootstrap":
                state = store.bootstrap(head)
            elif args.command == "create":
                request = parse(regular_read(args.request, store.policy["max_request_bytes"]))
                state = store.act("CREATE_HANDOFF", head, request=request)
            elif args.command == "respond":
                # Bound the read even for malformed/oversized untrusted input.
                try:
                    raw = regular_read(args.response, store.policy["max_response_bytes"])
                except ProtocolError as error:
                    # File access failures cannot be treated as a received response.
                    raise ProtocolError("RESPONSE_FILE_UNREADABLE") from error
                state = store.act("REVIEW_RESPONSE", head, response_raw=raw)
            elif args.command == "gate":
                state = store.act("HUMAN_GATE", head, reason=args.reason)
            else:
                state = store.act({"delivered": "DELIVERED", "complete": "COMPLETE"}[args.command], head)
        sys.stdout.buffer.write(canonical(state))
        return 1 if state["human_intervention_required"] else 0
    except (ProtocolError, OSError) as error:
        reason = str(error) if isinstance(error, ProtocolError) else "LOCAL_IO_FAILURE"
        print(reason, file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
